//! Emit `polars_cv/_generated/ops.py` from the inventory registry.
//!
//! Run via:
//!
//! ```bash
//! cargo run -p pcv-graph --bin dump_schema > polars-cv/python/polars_cv/_generated/ops.py
//! ```
//!
//! CI asserts `git diff --exit-code` on the generated file so any Rust-only
//! change to op contracts that forgets to regenerate fails the build.

use pcv_graph::contract::{AlphaMode, DTypeEffect, NdimEffect, OpContract};
use pcv_graph::registry::{iter_ops, OpRegistration};
use pcv_graph::WIRE_VERSION;

fn dtype_effect_py(e: DTypeEffect) -> &'static str {
    match e {
        DTypeEffect::Preserve => "DTypeEffect.PRESERVE",
        DTypeEffect::FixedU8 => "DTypeEffect.FIXED_U8",
        DTypeEffect::FixedF32 => "DTypeEffect.FIXED_F32",
        DTypeEffect::FixedF64 => "DTypeEffect.FIXED_F64",
        DTypeEffect::FixedI64 => "DTypeEffect.FIXED_I64",
        DTypeEffect::FixedU64 => "DTypeEffect.FIXED_U64",
        DTypeEffect::FixedU32 => "DTypeEffect.FIXED_U32",
        DTypeEffect::PromoteToFloat => "DTypeEffect.PROMOTE_TO_FLOAT",
        DTypeEffect::ConfigurableF32 => "DTypeEffect.CONFIGURABLE_F32",
    }
}

fn ndim_effect_py(e: NdimEffect) -> &'static str {
    match e {
        NdimEffect::Preserve => "NdimEffect.PRESERVE",
        NdimEffect::ReduceOne => "NdimEffect.REDUCE_ONE",
        NdimEffect::ToZero => "NdimEffect.TO_ZERO",
        NdimEffect::ToOne => "NdimEffect.TO_ONE",
        NdimEffect::ToThree => "NdimEffect.TO_THREE",
    }
}

fn alpha_mode_py(a: AlphaMode) -> &'static str {
    match a {
        AlphaMode::Passthrough => "AlphaMode.PASSTHROUGH",
        AlphaMode::StripProcessRestore => "AlphaMode.STRIP_PROCESS_RESTORE",
        AlphaMode::Drop => "AlphaMode.DROP",
        AlphaMode::NotApplicable => "AlphaMode.NOT_APPLICABLE",
    }
}

fn emit_contract_line(reg: &OpRegistration) {
    let OpContract {
        dtype_effect,
        ndim_effect,
        alpha_mode,
    } = *reg.contract;
    println!(
        "    \"{name}\": OpContract({d}, {n}, {a}),",
        name = reg.name,
        d = dtype_effect_py(dtype_effect),
        n = ndim_effect_py(ndim_effect),
        a = alpha_mode_py(alpha_mode),
    );
}

fn main() {
    println!("# AUTOGENERATED by `cargo run -p pcv-graph --bin dump_schema`. DO NOT EDIT.");
    println!("# Source of truth: `pcv-graph` op registry.");
    println!("from polars_cv._types import AlphaMode, DTypeEffect, NdimEffect, OpContract");
    println!();
    println!("WIRE_VERSION: int = {WIRE_VERSION}");
    println!();
    println!("OPERATION_CONTRACTS: dict[str, OpContract] = {{");

    let mut regs: Vec<&'static OpRegistration> = iter_ops().collect();
    regs.sort_by_key(|r| r.name);
    for reg in regs {
        emit_contract_line(reg);
    }

    println!("}}");
}
